// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;

    function setUp() public { c = new ReentrancyDAO(); }

    // fuzz parameters: caller address and a boolean switch choosing whether the callee should revert
    function testFuzz_property(address caller, bool calleeReverts) public {
        // keep caller non-zero to be a valid address
        vm.assume(caller != address(0));

        // Deploy a helper that either reverts on receive or accepts — we control via constructor
        ReverterOrRecorder helper = new ReverterOrRecorder(calleeReverts);

        // Fund caller so it can deposit if needed (we don't deposit here — we want to test withdrawAll with zero credit)
        vm.deal(caller, 1 ether);

        // The key distinguishing scenario: caller has zero credit. On the reference, withdrawAll should NOT attempt the external call and thus must NOT revert.
        // On the mutant, withdrawAll will attempt the external call when credit==0 and will revert when the callee reverts.

        // make the withdrawAll call from the helper address (so msg.sender inside c is helper) to let c.call helper when it tries to send funds
        // We need c to call the helper (msg.sender.call...) so pass helper as the msg.sender by having helper call withdrawAll.

        // helper will call c.withdrawAll() as itself
        bool ok;
        try helper.callWithdraw(address(c)) {
            ok = true;
        } catch {
            ok = false;
        }

        // Assert: on the correct contract, withdrawAll never reverts for any caller with zero credit — so ok must be true for calleeReverts == true and calleeReverts == false.
        // The mutant will make ok == false when calleeReverts == true (it calls and the helper reverts), so this assertion distinguishes them.
        assertTrue(ok);
    }
}

// Helper that either reverts on receive() or simply records funds. It also has a function to call c.withdrawAll() from itself.
contract ReverterOrRecorder {
    bool public shouldRevert;
    uint public receivedCount;
    uint public receivedTotal;

    constructor(bool _shouldRevert) payable {
        shouldRevert = _shouldRevert;
    }

    // receive will either revert or record the received value
    receive() external payable {
        if (shouldRevert) {
            revert("I always revert");
        }
        receivedCount += 1;
        receivedTotal += msg.value;
    }

    // helper to call withdrawAll on c as this contract
    function callWithdraw(address cAddr) external {
        ReentrancyDAO(cAddr).withdrawAll();
    }
}
